def cantor_numbering(N: int) -> str:
    if N == 0:
        return "0/1"
    elif N == 1:
        return "1/1"
    else:
        level = 1
        while N > 2 ** level:
            N -= 2 ** level
            level += 1
        if N % 2 == 0:
            return f"{N // 2}/{level}"
        else:
            return f"{level - N // 2}/{N // 2 + 1}"
