def verify_isbn(isbn: str) -> str:
    if len(isbn) != 13 or isbn[12] not in '0123456789X':
        return "Invalid ISBN format"

    def calculate_checksum(isbn):
        weights = [1, 3, 1, 3, 1, 3, 1, 3, 1, 3, 1, 3, 1]
        total = sum(int(digit) * weight for digit, weight in zip(isbn[:-1], weights))
        check_digit = (10 - (total % 10)) % 10
        return check_digit

    calculated_check_digit = calculate_checksum(isbn)
    if calculated_check_digit == int(isbn[-1]):
        return "Right"
    else:
        corrected_isbn = isbn[:-1] + str(calculated_check_digit)
        return corrected_isbn
