def count_passing_ways(n: int, m: int) -> int:
    if m == 0:
        return 1
    if n == 1:
        return 0
    dp = [[0] * (m + 1) for _ in range(n)]
    for i in range(n):
        dp[i][0] = 1
    for i in range(1, n):
        dp[i][1] = dp[(i - 1) % n][0] + dp[(i + 1) % n][0]
    for i in range(2, m + 1):
        for j in range(1, n):
            dp[j][i] = dp[(j - 1) % n][i - 1] + dp[(j + 1) % n][i - 1]
    return dp[0][m]
```

