def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x:
        return 0
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if i < j * x:
                dp[i][j] = 0
            elif j == 1:
                dp[i][j] = 1
            else:
                dp[i][j] = dp[i - 1][j] + dp[i - j * x][j - 1]
    return dp[n][k]
```

