from collections import deque

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    if A == B:
        return 0

    queue = deque([(A, 0)])
    visited = set()

    while queue:
        current, steps = queue.popleft()
        if current == B:
            return steps

        for rule in rules:
            if current.startswith(rule[0]):
                new_string = current.replace(rule[0], rule[1])
                if new_string not in visited:
                    visited.add(new_string)
                    queue.append((new_string, steps + 1))

        if steps >= 10:
            return "NO ANSWER!"

    return "NO ANSWER!"
```

